<template>
 <view :class="[petThemeClass,'composition-page ui-v2',{'studio-busy':transactionBusy}]" :style="[appThemeStyle,insets]">
  <view class="composition-nav"><button @click="back">{{rootPage?'回首页':'返回'}}</button><view><text class="nav-title">{{resolved?.template?.name||'制作这一页'}}</text><text class="nav-subtitle">{{config?.mode==='deceased'?'把想念留在纸上':'这一页的日常'}}</text></view><button @click="panel='about'">···</button></view>
  <view v-if="recordReadError" class="record-read-error" :style="{'--ui-font-scale':uiFontScale}" role="alert"><text class="read-error-title">资料暂时没能读取</text><text>为保护已有内容，暂不开放编辑。请重试读取。</text><button @click="retryRead">重新读取</button></view>
  <view v-else-if="needsSource" class="source-empty"><text class="empty-title">从一条记录开始</text><text>先选好想留下的那一天。</text><button @click="selectRecord">选择一条记录</button><button @click="goHome">回到首页</button></view>
  <view v-else-if="waitingScope" class="source-empty"><text>正在确认这份记录的归属…</text></view>
  <template v-else-if="config">
   <view class="work-stage" :class="{'stamp-landing':stampLanding}">
    <scroll-view v-if="session.pages.length" scroll-y class="stage-pages"><image v-for="(url,i) in session.pages" :key="url" :src="url" mode="aspectFit" class="stage-image"/><text v-if="session.pages.length>1" class="page-count">共 {{session.pages.length}} 页 · 向下查看</text></scroll-view>
    <view v-else class="stage-empty"><text>{{session.state==='rendering'?'正在绘制这一页…':recovery?'继续整理这份草稿':'选一点内容，留在纸上'}}</text><button v-if="session.state!=='rendering'" @click="openPanel('content')">{{healthRows.length?'选择文字、照片或观察':'选择内容'}}</button><button v-if="recovery" @click="recoverDraft">保留草稿，开始可用的新版本</button><button v-if="session.state==='failed'" @click="preview">重新绘制</button></view>
    <text v-if="transactionBusy" class="render-progress">正在绘制新版本…</text><view v-if="sourceChanged" class="source-banner"><text>这一页用到的原记录已更新</text><button @click="keepSnapshot">沿用当前快照</button><button @click="refreshSource">使用新内容</button></view>
   </view>
   <view v-if="compositionConflict" class="composition-conflict" role="alert" :style="{'--ui-font-scale':uiFontScale}"><text class="composition-conflict-title">这份草稿在别处有变化</text><text>{{notice||'当前版式仅保留在此页。'}}</text><text>可将当前画面存入册页，或确认后读取已保存的草稿。</text><button @click="reloadCompositionDraft">重新读取草稿</button></view>
   <text v-if="notice&&!compositionConflict" class="notice" role="status" :style="{'--ui-font-scale':uiFontScale}">{{notice}}</text>
   <view class="studio-tools"><button v-for="tool in [{id:'content',label:'内容',icon:'compose'},{id:'paper',label:'纸面',icon:'list'},{id:'seal',label:'印记',icon:'vip'}]" :key="tool.id" :class="{'tool-active':panel===tool.id}" :disabled="transactionBusy" @click="openPanel(tool.id)"><uni-icons :type="tool.icon" size="21" color="currentColor"/>{{tool.label}}</button></view>
   <view v-if="!config.recipe" class="template-heading"><text>选择版式</text><button v-if="previousVariant" @click="restoreVariant">返回上一版</button></view>
   <scroll-view v-if="!config.recipe" scroll-x class="template-strip"><view class="template-track"><button v-for="t in templates" :key="t.id" :disabled="transactionBusy" :class="{selected:config.template.id===t.id}" @click="chooseTemplate(t.id)"><view class="thumb-frame"><image v-if="thumbs[t.id]" :src="thumbs[t.id]" mode="aspectFit"/><text v-else class="thumb-loading">正在绘制</text><text class="thumb-label">{{config.template.id===t.id?'已选':exampleThumbs[t.id]?'版式示例':''}}</text></view><text>{{t.name}}</text></button></view></scroll-view>
   <view class="finish-actions"><AppButton :disabled="!canFinish" @click="saveWork">存入册页</AppButton><AppButton variant="primary" class="primary" :disabled="!canFinish" @click="exportImages">{{session.pages.length>1?'保存 '+session.pages.length+' 张图片':'保存图片'}}</AppButton></view>
  </template>
  <template v-if="!recordReadError">
  <view v-if="panel||proposal" class="panel-mask" @click="cancelPanel"/>
  <view v-if="proposal" class="composition-panel"><view class="panel-head"><text>为这个版式另做一版</text><button @click="cancelProposal">取消</button></view><scroll-view scroll-y class="panel-scroll"><text class="caption">当前作品会保留。新版本仅包含下方确认的内容，不改动原记录。</text><text class="panel-notice">{{proposalSummary}}</text><text v-if="panelNotice" class="panel-notice">{{panelNotice}}</text><view v-if="['quote','letter','habit'].includes(proposal.config.template.id)" class="work-writing"><text class="group-title">选择原话 · 可直接使用或亲手节选</text><textarea v-model="variantText" :maxlength="-1"/></view><button class="action primary" :disabled="transactionBusy" @click="confirmVariant">确认内容，另做一版</button><button class="action" @click="chooseTemplate('daily_record')">保留全部，用今日记录卡</button><button class="action" @click="cancelProposal">继续用当前版式</button></scroll-view></view>
  <view v-else-if="panel==='about'" class="composition-panel"><view class="panel-head"><text>分享前检查</text><button @click="cancelPanel">完成</button></view><view class="about-copy">这些选择只改变本作品，不改动原记录或问诊资料。隐藏系统姓名不会改写你亲手写下的文字，也不会处理照片中的姓名。<button v-if="savedWork" class="action" @click="newVersion">按最新资料制作新版</button></view></view>
  <view v-else-if="panel && config" class="composition-panel"><view class="panel-head"><button @click="cancelPanel">取消</button><text>{{panel==='content'?'这张卡放什么':panel==='paper'?'纸面细节':'盖上它的印记'}}</text><button :disabled="transactionBusy" @click="applyPanel">应用</button></view><scroll-view scroll-y class="panel-scroll">
   <text class="caption">这里只决定卡片上显示什么，不会改动原记录或问诊资料。</text>
   <text v-if="healthDisclosureSelected" class="caption health-disclosure">卡片只展示你选的项目，不代表完整健康情况。</text>
   <text v-if="panelNotice" class="panel-notice">{{panelNotice}}</text>
   <view v-if="panel==='content'">
   <view v-if="editConfig.recipe" class="recipe-editor"><input class="recipe-title" :value="editConfig.recipe.title" placeholder="作品标题" @input="editConfig.recipe.title=$event.detail.value;editChanged()"/>
    <text class="caption">{{editConfig.recipe.type==='comparison'?'左右顺序、说明和日期显示只影响本作品。':'第一项是封面。取材、顺序与文字只影响本作品。'}}</text>
    <view v-for="(item,i) in editConfig.recipe.items" :key="i+':'+item.recordId" class="recipe-item"><text>{{i+1}} · {{recipeLabel(item)}}</text><view class="recipe-actions"><button :disabled="i===0" @click="moveRecipeItem(i,-1)">{{editConfig.recipe.type==='comparison'?'移到左边':'前移 / 设为封面'}}</button><button :disabled="i===editConfig.recipe.items.length-1" @click="moveRecipeItem(i,1)">{{editConfig.recipe.type==='comparison'?'移到右边':'后移'}}</button><button v-if="editConfig.recipe.type==='booklet'" @click="removeRecipeItem(i)">移出本册</button></view>
    <textarea v-if="editConfig.recipe.type==='booklet'" :value="recipeText(item)" :maxlength="-1" @input="editRecipeItem(i,'text',$event.detail.value)"/><view v-if="editConfig.recipe.type==='booklet'" class="recipe-actions"><button @click="editRecipeItem(i,'text',undefined);editRecipeItem(i,'textVersion','original')">使用原文</button><button @click="editRecipeItem(i,'text',undefined);editRecipeItem(i,'textVersion','accepted')">使用已采用文字</button></view>
    <input v-if="editConfig.recipe.type==='comparison'" :value="item.caption===undefined?(recipePhotos(item).find(m=>m.id===item.assetId)?.caption||''):item.caption" placeholder="这一张的说明" @input="editRecipeItem(i,'caption',$event.detail.value)"/>
    <view class="recipe-actions"><button @click="editRecipeItem(i,'showDate',item.showDate===false)">{{item.showDate===false?'显示日期':'隐藏日期'}}</button><button @click="editRecipeItem(i,'fit',item.fit==='cover'?'contain':'cover')">{{item.fit==='cover'?'当前取景填满':'当前显示完整照片'}}</button><button @click="editRecipeItem(i,'fit','contain');editRecipeItem(i,'cropX',0.5);editRecipeItem(i,'cropY',0.5)">重置取景</button></view>
    <template v-if="item.fit==='cover'"><text>水平取景</text><slider :value="(item.cropX??0.5)*100" @change="editRecipeItem(i,'cropX',$event.detail.value/100)"/><text>垂直取景</text><slider :value="(item.cropY??0.5)*100" @change="editRecipeItem(i,'cropY',$event.detail.value/100)"/></template>
    <view class="recipe-actions"><button v-for="photo in recipePhotos(item)" :key="photo.id" @click="editRecipeItem(i,'assetId',photo.id)">{{item.assetId===photo.id?'✓ ':''}}{{photo.caption||'记录中的照片'}}</button><button v-if="editConfig.recipe.type==='booklet'" @click="editRecipeItem(i,'assetId','')">这一页只用文字</button></view></view>
    <view v-if="editConfig.recipe.type==='booklet'"><text class="group-title">增添来源</text><button v-for="row in source.recipeRecords.filter(r=>!editConfig.recipe.items.some(i=>i.recordId===r.id)).slice(0,30)" :key="row.id" @click="addRecipeSource(row.id)">{{row.title||row.lifeText||row.original||'照片记录'}}</button></view>
   </view>
   <view v-for="group in (editConfig.recipe?groups.filter(g=>g.name==='名字与日期'):groups)" :key="group.name" class="field-group"><text class="group-title">{{group.name}}</text>
    <view v-for="key in group.keys.filter(k=>hasSource(k)||editConfig.requested[k]==='show')" :key="key" class="field-choice"><view><text>{{labels[key]}}</text><text class="field-state">{{stateLabel(key)}}</text></view><switch :checked="isSelected(key)" color="#596650" @change="toggle(key,$event.detail.value)"/><button v-if="panelResolved?.states[key]==='unsupported'" class="remove-choice" @click="toggle(key,false)">从本作品移除</button></view>
   </view>
   <view v-for="key in Object.keys(labels).filter(k=>(source?.fields[k]?.length||0)>1 && !k.startsWith('media.') && k!=='health.items')" :key="'source-'+key" class="source-selection"><text class="group-title">{{labels[key]}} · 选择来源</text><button v-for="row in source.fields[key]" :key="JSON.stringify(row.ref)" :class="{selected:!editConfig.selections.fields[key]||editConfig.selections.fields[key].includes(JSON.stringify(row.ref))}" @click="selectFieldSource(key,row.ref)">{{row.ref.eventDateLabel}} · {{String(row.value)}}</button></view><view v-for="key in Object.keys(labels).filter(k=>source?.fields[k]?.some(r=>r.candidate))" :key="'version-'+key" class="paper-options"><text>{{labels[key]}} · 文字版本</text><button :class="{selected:editConfig.selections.textVersions[key]!=='acceptedCandidate'}" @click="textVersion(key,'original')">原文</button><button :class="{selected:editConfig.selections.textVersions[key]==='acceptedCandidate'}" @click="textVersion(key,'acceptedCandidate')">已采用并编辑的版本</button></view>
   <view class="health-choice" v-if="editConfig.requested['health.items']==='show'"><button @click="basicHealth">选择有结果的基础观察</button><button v-for="h in healthFields.filter(h=>healthRows.some(r=>r.key===h.key))" :key="h.key" :disabled="!healthRows.some(r=>r.key===h.key)" :class="{selected:editConfig.selections.healthKeys.includes(h.key)}" @click="healthSelect(h.key)">{{h.label}} · {{healthRows.filter(r=>r.key===h.key).map(r=>r.value).join(' / ')||'尚无具体观察'}}</button></view>
   <view v-if="!editConfig.recipe && availablePhotos.length" class="photo-picks"><text class="group-title">明确选择照片与顺序</text><button v-for="(row,i) in availablePhotos" :key="row.value.id" :class="{selected:editConfig.selections.photoIds.includes(row.value.id)}" @click="photoSelect(row.value.id)"><image :src="photoUrls[row.value.id]" mode="aspectFit"/><text>{{editConfig.selections.photoIds.indexOf(row.value.id)>=0?'已选 '+(editConfig.selections.photoIds.indexOf(row.value.id)+1):'选择照片 '+(i+1)}}</text></button></view>
   <view v-if="!editConfig.recipe && ['letter','quote','habit'].includes(editConfig.template.id)" class="work-writing"><text class="group-title">{{labels['text.'+editConfig.template.id]}} · 只调整本作品</text><textarea :value="editConfig.custom['text.'+editConfig.template.id]?.text || ''" :maxlength="-1" placeholder="亲手选一句话，或写下这一页的正文。" @input="writeWork('text.'+editConfig.template.id,$event.detail.value)"/><button @click="useLifeBody">明确使用生活正文</button><input v-if="editConfig.template.id==='letter'" placeholder="称呼（可选，不自动填写）" :value="editConfig.custom['identity.salutation']?.text||''" @input="writeWork('identity.salutation',$event.detail.value)"/><input v-if="editConfig.template.id==='letter'" placeholder="署名（可选）" :value="editConfig.custom['identity.signature']?.text||''" @input="writeWork('identity.signature',$event.detail.value)"/></view>
   <view class="date-choices" v-if="!editConfig.recipe && hasSource('date.display')"><text>日期含义</text><button :class="{selected:editConfig.dateKind!=='written'}" @click="setDateKind('event')">这件事的日期</button><button :class="{selected:editConfig.dateKind==='written'}" @click="setDateKind('written')">写下这段话的日期</button></view>
   </view><view v-if="panel==='paper'" class="field-group"><text class="group-title">纸面细节</text><view class="field-choice"><text>正文横线</text><switch :checked="editConfig.presentation.ruleLines" @change="paper('ruleLines',$event.detail.value)"/></view><view v-if="!editConfig.recipe" class="paper-options"><button v-for="(label,id) in {none:'无插画',window:'窗影',botanical:'植物线描',postmark:'明信片线饰'}" :key="id" :class="{selected:(editConfig.presentation.illustrationId||'none')===id}" @click="paper('illustrationId',id==='none'?null:id)"><view :class="['decoration-swatch',id]">{{id==='window'?'⊞':id==='botanical'?'⌁':id==='postmark'?'≋':'·'}}</view>{{label}}</button></view><view class="field-choice"><text>低对比纸纹</text><switch :checked="!!editConfig.presentation.paperTextureId" @change="paper('paperTextureId',$event.detail.value?'fine-lines':null)"/></view><view class="paper-options"><button v-for="(label,id) in {none:'无相框',thin:'细边',paper:'相纸边'}" :key="id" :class="{selected:editConfig.presentation.photoFrameId===id}" @click="paper('photoFrameId',id)">{{label}}</button></view><view class="field-choice"><text>小品牌页脚</text><switch :checked="editConfig.presentation.footerBrand" @change="paper('footerBrand',$event.detail.value)"/></view>
    </view><view v-if="panel==='seal'"><button class="stamp-action" :disabled="!source?.seal" @click="stamp">{{editConfig.presentation.seal.enabled?'撤回印记':'盖上它的印记'}}</button><text v-if="!source?.seal" class="caption">尚无已确认印记，请先在宠物档案制作。</text><view class="seal-swatches"><button v-for="(style,i) in ['vermilion','emboss']" :key="style" :class="{selected:editConfig.presentation.seal.style===style}" @click="setSeal('style',style)"><image v-if="sealThumbs[i]" :src="sealThumbs[i]" mode="aspectFit"/>{{i===0?'朱印':'压印'}}</button></view><view class="paper-options"><AppSegmented :model-value="editConfig.presentation.seal.placement" :options="[{value:'right',label:'右下'},{value:'left',label:'左下'},{value:'free',label:'自由放置'}]" @change="setSeal('placement',$event)"/><button v-for="(label,id) in {small:'小',standard:'标准'}" :key="id" :class="{selected:editConfig.presentation.seal.size===id}" @click="setSeal('size',id)">{{label}}</button></view>
   </view><button class="quiet" @click="showEmpty=!showEmpty">查看其他内容</button><text v-if="showEmpty" class="caption">{{Object.keys(labels).filter(k=>!hasSource(k)).map(k=>labels[k]+'：这一天还没有独立来源').join('；')}}</text>

  </scroll-view></view>
  <FreeSealEditor v-if="freeEditor" v-bind="freeEditor" @cancel="freeEpoch++;freeEditor=null" @complete="completeFreeSeal"/></template><NarrativeCanvas ref="canvas"/><NarrativeCanvas ref="thumbnailCanvas"/><PetSealMaker ref="sealMaker"/>
 </view>
</template>
<script>
export {default} from '../../common/card-studio-page.js';
</script>
<style scoped>
.recipe-editor input{height:48px;min-height:48px;box-sizing:border-box;background:var(--ui-input);color:var(--ui-ink);border-radius:14px;padding:10px;font-size:16px;}.recipe-item{padding:20px 0;border-bottom:1px solid var(--ui-line);font-size:14px;line-height:1.8;}.recipe-item textarea{width:100%;min-height:120px;font-size:16px;line-height:26px;color:var(--ui-ink);}.recipe-actions{display:flex;gap:8px;flex-wrap:wrap;}.recipe-actions button,.recipe-editor>view>button{min-height:44px;font-size:13px;background:transparent;color:var(--ui-muted);margin:0;}
