color:var(--ui-muted)}.conflict-banner{margin:12px 24px;padding:16px;background:var(--ui-surface);border:1px solid #d9c7a5;border-radius:14px;font-size:13px}.conflict-banner text{display:block;line-height:1.8}.conflict-banner button{display:inline-block;background:none;color:var(--ui-muted);font-size:12px;padding:4px 8px}.panel-mask{position:fixed;inset:0;background:#222b2255;z-index:90}.composition-panel{position:fixed;left:0;right:0;bottom:0;z-index:91;background:var(--ui-surface);border-radius:24px 24px 0 0;max-height:72vh;padding-bottom:var(--creative-bottom)}.panel-head{display:flex;justify-content:space-between;align-items:center;padding:14px 22px}.panel-head button{margin:0;background:transparent;font-size:13px;color:var(--ui-ink)}.panel-scroll{height:60vh;padding:0 22px 24px;box-sizing:border-box}.field-group{margin:24px 0}.group-title{display:block;font-size:16px;margin:14px 0}.field-choice{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;padding:11px 0;border-bottom:1px solid var(--ui-line);font-size:14px}.field-state{display:block;font-size:10px;color:var(--ui-muted);margin-top:4px}.health-choice{padding:12px;background:var(--ui-surface);border-radius:12px}.health-choice>text{font-size:12px;line-height:1.8}.health-choice button{font-size:12px;white-space:normal;line-height:1.7;margin:10px 0;padding:8px;background:var(--ui-surface);text-align:left;color:var(--ui-muted)}.photo-picks{display:flex;flex-wrap:wrap;gap:12px}.photo-picks>.group-title{width:100%}.photo-picks button{width:45%;padding:6px;font-size:12px;background:var(--ui-surface)}.photo-picks image{width:100%;height:100px}.work-writing textarea{width:100%;min-height:140px;font-size:15px;line-height:1.8;background:var(--ui-surface);box-sizing:border-box;padding:12px}.work-writing input{height:44px;margin:10px 0;border-bottom:1px solid var(--ui-line)}.paper-options,.date-choices{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.paper-options>button,.date-choices button{margin:0;background:var(--ui-surface);font-size:12px;padding:7px 10px;color:var(--ui-muted);line-height:1.8}.decoration-swatch{font-size:30px;line-height:45px;color:var(--ui-muted)}.seal-swatches{display:flex;gap:16px}.seal-swatches button{flex:1;background:var(--ui-surface);font-size:13px}.seal-swatches image{width:100%;height:110px}.stamp-action{background:var(--ui-surface);color:var(--ui-muted);font-size:14px;margin:16px 0}.quiet,.remove-choice{font-size:12px;color:var(--ui-muted);background:none}.conflict-label{display:block;color:var(--ui-muted);font-size:12px;margin:12px 0}.stamp-landing{animation:stampLand .3s ease-out}@keyframes stampLand{from{opacity:.8;transform:translateY(-2px)}to{opacity:1;transform:none}}

/* Preview-first studio. Insets are from the real window, not a guessed phone. */
.composition-page{display:flex;flex-direction:column;background:var(--ui-surface);padding-bottom:var(--creative-bottom);overflow:hidden;color:var(--ui-ink)}
.composition-nav{height:54px;flex-shrink:0;background:var(--ui-surface);border-bottom:1px solid var(--ui-line);padding:0 16px;text-align:center}.composition-nav button{min-width:44px;min-height:44px;font-size:15px;line-height:44px}.nav-title{display:block;font-size:18px!important;font-weight:500}.nav-subtitle{display:block;font-size:11px!important;margin-top:2px;color:var(--ui-muted)}
.work-stage{position:relative;flex:1;min-height:150px;padding:16px 20px 8px;background:var(--ui-surface)}.stage-pages{height:100%}.stage-image{display:block;width:100%;height:100%;min-height:150px;filter:drop-shadow(0 5px 7px #383c2722)}.stage-pages .uni-scroll-view-content{height:100%}.stage-empty{height:100%;display:flex;flex-direction:column;justify-content:center;align-items:center;background:var(--ui-surface);margin:0 18px;padding:20px;font-size:16px;text-align:center;gap:16px}.stage-empty button{background:var(--ui-surface);color:var(--ui-ink);font-size:15px;min-height:44px}.page-count{font-size:11px;display:block;text-align:right}.notice{padding:8px 20px;font-size:calc(14px * var(--ui-font-scale,1));background:var(--ui-surface);flex-shrink:0}
.studio-tools{display:flex;height:50px;flex-shrink:0;background:var(--ui-surface);border-top:1px solid var(--ui-line);border-bottom:1px solid var(--ui-line)}.studio-tools button{flex:1;border-radius:0;background:none;font-size:16px;color:var(--ui-ink);margin:0;line-height:50px;border-right:1px solid var(--ui-line)}.studio-tools button:last-child{border:0}.template-heading{display:flex;justify-content:space-between;align-items:center;padding:10px 20px 3px;font-size:13px;background:var(--ui-surface)}.template-heading button{font-size:12px;background:none;color:var(--ui-muted);margin:0;padding:0}.template-strip{padding:5px 0 10px;height:137px;box-sizing:border-box;flex-shrink:0;background:var(--ui-surface)}.template-track{gap:12px;padding:0 20px}.template-track button{padding:4px;width:88px;background:transparent;font-size:12px;line-height:1.4;border-radius:0;color:var(--ui-ink)}.thumb-frame{position:relative;height:96px;width:78px;background:var(--ui-surface);margin-bottom:5px}.template-track image{width:100%;height:100%}.thumb-label{position:absolute;bottom:0;right:0;background:var(--ui-group);color:var(--ui-ink);font-size:9px;padding:2px}.selected .thumb-label{background:#596650;color:white}.thumb-loading{font-size:10px;display:block;padding-top:35px;color:var(--ui-muted)}
.finish-actions{padding:12px 20px;flex-shrink:0;gap:12px;background:var(--ui-surface);border-top:1px solid var(--ui-line)}.finish-actions button{min-height:46px;background:transparent;border:1px solid var(--ui-line);color:var(--ui-ink);font-size:16px;line-height:44px;border-radius:9px;margin:0}.finish-actions .primary{background:#55634b;color:#fff;border-color:var(--ui-line)}.finish-actions button[disabled]{opacity:.45}
.source-empty{display:flex;flex-direction:column;gap:20px;padding:50px 24px;font-size:15px}.empty-title{font-size:24px}.source-empty button{font-size:16px}.source-banner{position:absolute;bottom:10px;left:24px;right:24px;background:var(--ui-surface);padding:12px;font-size:13px}.source-banner button{display:inline-block;font-size:13px;background:none;color:var(--ui-muted)}.source-banner text{display:block}
.composition-panel{max-height:80vh;border-radius:20px 20px 0 0;background:var(--ui-surface)}.panel-head{height:58px;font-size:17px;padding:8px 20px;border-bottom:1px solid var(--ui-line)}.panel-head button{font-size:15px;min-height:44px;line-height:44px;padding:0 8px}.panel-scroll{height:62vh}.field-choice{font-size:16px;min-height:58px}.caption{font-size:13px;padding-top:12px}.field-state{font-size:12px}.group-title{font-size:16px;font-weight:500}.health-choice button{font-size:15px;min-height:48px}.photo-picks button{font-size:14px}.paper-options>button{font-size:14px;min-height:44px}.seal-swatches button{font-size:16px}.panel-notice{display:block;color:var(--ui-muted);font-size:14px;line-height:1.8;margin:12px 0}.action{font-size:16px;min-height:46px;margin:16px 0;background:var(--ui-surface);color:var(--ui-ink)}.action.primary{background:#56644d;color:white}.about-copy{padding:24px;font-size:15px;line-height:1.8}.work-writing textarea{font-size:16px;min-height:190px;margin-top:14px}.stamp-action{min-height:46px;font-size:16px}
@media(max-height:700px){.template-strip{height:111px}.thumb-frame{height:74px}.studio-tools{height:44px}.studio-tools button{line-height:44px}.finish-actions{padding:8px 16px}.work-stage{padding-top:8px}}
.render-progress{position:absolute;bottom:12px;left:0;right:0;text-align:center;font-size:12px;color:var(--ui-muted);background:var(--ui-surface);padding:6px}

.record-read-error{margin:24px 0;padding:24px 20px;border-radius:20px;background:#f5efe3;color:#403a32;display:flex;flex-direction:column;gap:14px;line-height:1.7;overflow-wrap:anywhere;font-size:calc(14px * var(--ui-font-scale,1));}.record-read-error .read-error-title{font-size:calc(20px * var(--ui-font-scale,1));font-weight:600;}.record-read-error button{margin:6px 0 0;min-height:44px;padding:10px 16px;line-height:1.5;white-space:normal;background:#596650;color:#fffdf8;border-radius:12px;font-size:inherit;}
.composition-page .record-read-error{margin:24px 16px;}
